BYTES = {"bf16_weights": 2, "bf16_grads": 2,
         "fp32_master": 4, "adam_m": 4, "adam_v": 4}

def bytes_per_param(stage: int, n_gpus: int) -> float:
    optim = BYTES["fp32_master"] + BYTES["adam_m"] + BYTES["adam_v"]
    grads, weights = BYTES["bf16_grads"], BYTES["bf16_weights"]
    if stage >= 1:
        optim /= n_gpus
    if stage >= 2:
        grads /= n_gpus
    if stage >= 3:
        weights /= n_gpus
    return weights + grads + optim

def model_state_gb(params_b: float, stage: int, n_gpus: int) -> float:
    return params_b * bytes_per_param(stage, n_gpus)

for stage in range(4):
    print(f"ZeRO-{stage}: {model_state_gb(7, stage, 8):.2f} GB/GPU")

